//! Session recap (`session-runtime` → Session recap): one or two sentences about what a
//! Session did and what comes next, generated by the `small` model role and stored as a
//! durable event, so every client can show it and re-opening never pays twice.

use cyber_llm::catalog::{ModelRole, compute_cost};
use cyber_llm::{Message, collect};
use serde::{Deserialize, Serialize};

use super::events::{AUXILIARY_USAGE, AuxiliaryUsage, RECAP_GENERATED, event};
use super::model::{Entry, SessionState, text_of};
use super::{Inner, Runtime, RuntimeError};

const SYSTEM: &str = "You summarize a coding session for the user who is returning to it. \
Write one or two sentences in the first person past tense: what was done, then what comes \
next. Reply with the summary only, no preamble.";
/// The most output the recap call may produce.
pub const MAX_OUTPUT_TOKENS: u32 = 120;
/// Stored recaps are trimmed to this many characters.
pub const MAX_CHARS: usize = 400;
/// The conversation sent to the model is the tail of this many characters.
const MAX_INPUT_CHARS: usize = 16_000;
/// Each message of the conversation is cut to this many characters.
const MAX_ENTRY_CHARS: usize = 2_000;
/// The `ConflictError` reason of a Session without a finished Turn.
pub const NOTHING_TO_RECAP: &str = "nothing_to_recap";

/// The latest Session recap.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, schemars::JsonSchema)]
pub struct Recap {
    pub text: String,
    /// The model reference that wrote it.
    pub model: String,
    /// The last durable sequence it covers.
    pub through_seq: i64,
    /// When it was generated (the event time); filled from the stored event.
    #[serde(default)]
    pub generated_ms: i64,
}

/// The `session.recap.generated.1` payload.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub(super) struct RecapGenerated {
    pub text: String,
    pub model: String,
    pub through_seq: i64,
}

/// `text` without control characters or bidirectional overrides, so no client can be
/// driven by escape sequences a model wrote.
pub(crate) fn printable(text: &str) -> String {
    text.chars()
        .filter(|&c| {
            !c.is_control() && !matches!(c, '\u{202a}'..='\u{202e}' | '\u{2066}'..='\u{2069}')
        })
        .collect()
}

/// Strip reasoning tags and control characters, collapse whitespace and cap at
/// [`MAX_CHARS`].
pub(crate) fn clean(raw: &str) -> String {
    let mut text = raw.to_string();
    while let (Some(start), Some(end)) = (text.find("<think>"), text.find("</think>")) {
        if end < start {
            break;
        }
        text.replace_range(start..end + "</think>".len(), "");
    }
    let text = printable(&text.split_whitespace().collect::<Vec<_>>().join(" "));
    let text = text.trim_matches(|c| c == '"' || c == '\'').trim();
    if text.chars().count() <= MAX_CHARS {
        return text.to_owned();
    }
    let cut: String = text.chars().take(MAX_CHARS - 1).collect();
    format!("{}…", cut.trim_end())
}

fn clip(text: &str, max: usize) -> String {
    if text.chars().count() <= max {
        return text.to_owned();
    }
    let cut: String = text.chars().take(max).collect();
    format!("{cut}…")
}

/// The conversation as plain text: user and assistant messages with the tools each
/// assistant message called, keeping the newest [`MAX_INPUT_CHARS`].
fn transcript(state: &SessionState) -> String {
    let mut out = String::new();
    for entry in &state.entries {
        match entry {
            Entry::User { parts, .. } => {
                out.push_str(&format!(
                    "User: {}\n",
                    clip(&text_of(parts), MAX_ENTRY_CHARS)
                ));
            }
            Entry::Assistant(a) => {
                let tools: Vec<&str> = a
                    .calls
                    .iter()
                    .filter_map(|id| state.calls.get(id).map(|c| c.name.as_str()))
                    .collect();
                if !a.text.trim().is_empty() {
                    out.push_str(&format!("Assistant: {}\n", clip(&a.text, MAX_ENTRY_CHARS)));
                }
                if !tools.is_empty() {
                    out.push_str(&format!("Assistant used tools: {}\n", tools.join(", ")));
                }
            }
            Entry::System { .. } => {}
        }
    }
    let skip = out.chars().count().saturating_sub(MAX_INPUT_CHARS);
    out.chars().skip(skip).collect()
}

impl Inner {
    async fn generate_recap(&self, id: &str) -> Result<Recap, RuntimeError> {
        let handle = self.handle(id).await?;
        let _one = handle.recap.lock().await;
        let (conversation, session_model, through_seq) = {
            let state = handle.state.lock().await;
            if state.finished_seq == 0 {
                return Err(RuntimeError::Conflict(NOTHING_TO_RECAP.into()));
            }
            if let Some(recap) = state
                .recap
                .as_ref()
                .filter(|r| r.through_seq >= state.finished_seq)
            {
                return Ok(recap.clone());
            }
            (transcript(&state), state.info.model.clone(), state.last_seq)
        };
        let model = self
            .resolver
            .role(ModelRole::Small)
            .unwrap_or(session_model);
        let resolved = self.resolver.resolve(&model).map_err(RuntimeError::Model)?;
        let mut request = resolved.template.clone();
        request.system = vec![SYSTEM.into()];
        request.messages = vec![Message::user_text(conversation)];
        request.tools = Vec::new();
        request.reasoning = None;
        request.max_output_tokens = Some(MAX_OUTPUT_TOKENS);
        // Like a title, a recap is bookkeeping, not a prompt: Copilot does not count it.
        request.initiator = Some(cyber_llm::Initiator::Agent);
        self.check_budget(&handle).await?;
        let started = std::time::Instant::now();
        let stream = resolved
            .adapter
            .stream(request)
            .await
            .map_err(|e| RuntimeError::Model(e.to_string()))?;
        let out = collect(stream, |_| {})
            .await
            .map_err(|e| RuntimeError::Model(e.to_string()))?;
        let text = clean(&out.text);
        let usage = event(
            AUXILIARY_USAGE,
            &AuxiliaryUsage {
                provider: resolved.provider.clone(),
                model: model.clone(),
                purpose: "recap".into(),
                call_id: None,
                duration_ms: started.elapsed().as_millis().min(u64::MAX as u128) as u64,
                usage: out.usage,
                cost: compute_cost(resolved.cost.as_ref(), &out.usage),
            },
        );
        let mut events = vec![usage];
        if !text.is_empty() {
            events.push(event(
                RECAP_GENERATED,
                &RecapGenerated {
                    text,
                    model,
                    through_seq,
                },
            ));
        }
        let mut state = handle.state.lock().await;
        self.commit_locked(&mut state, events)?;
        let recap = state.recap.clone().filter(|r| r.through_seq == through_seq);
        drop(state);
        self.observe_budget(&handle).await?;
        recap.ok_or_else(|| RuntimeError::Model("The model returned an empty recap".into()))
    }
}

impl Runtime {
    /// The latest stored recap of a Session, if any.
    pub async fn recap(&self, session_id: &str) -> Result<Option<Recap>, RuntimeError> {
        let handle = self.inner.handle(session_id).await?;
        let state = handle.state.lock().await;
        Ok(state.recap.clone())
    }

    /// The stored recap when it covers the latest finished Turn, else a new one.
    pub async fn generate_recap(&self, session_id: &str) -> Result<Recap, RuntimeError> {
        self.inner.generate_recap(session_id).await
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cleans_and_caps_the_recap() {
        assert_eq!(
            clean("<think>plan</think>\n  I fixed the login test.\n\nNext I'll  add CI. "),
            "I fixed the login test. Next I'll add CI."
        );
        let long = clean(&"word ".repeat(200));
        assert_eq!(long.chars().count(), MAX_CHARS);
        assert!(long.ends_with('…'));
        assert_eq!(clean("<think>only reasoning</think>"), "");
        assert_eq!(
            clean("I \u{1b}[2Jcleared\u{7}\nthe \u{9b}screen\u{202e}."),
            "I [2Jcleared the screen."
        );
    }
}
